template<class T>T read(std::istream&in){T value{};in>>value;CHECK(bool(in));return value;}
uint32_t word(const std::vector<uint8_t>&b,size_t at){return uint32_t(b[at])|uint32_t(b[at+1])<<8|uint32_t(b[at+2])<<16|uint32_t(b[at+3])<<24;}
float real(uint32_t bits){float value;std::memcpy(&value,&bits,4);return value;}
uint32_t bits(float value){uint32_t result;std::memcpy(&result,&value,4);return result;}
void put(std::vector<uint8_t>&b,size_t at,uint32_t v){for(unsigned n=0;n<4;++n)b[at+n]=uint8_t(v>>(8*n));}
void seal(std::vector<uint8_t>&b,size_t first=0,size_t size=0){if(!size)size=b.size()-first;put(b,first+12,uint32_t(size));put(b,first+16,encore::crc32(b.data()+first+32,size-32));}
bool event_value(WorldDamageEventKind kind,size_t column,double actual,double expected){
 // Native JSON prints these Vector2/real_t coordinates with six decimals.
 // Compare their actual binary32 semantic value;RNG distance remains binary64.
 if(kind==WorldDamageEventKind::FlyingNumber&&(column==1||column==2))return std::isfinite(actual)&&std::isfinite(expected)&&bits(float(actual))==bits(float(expected));
 return actual==expected;
}
